'use strict';
const fs=require('node:fs'),path=require('node:path'),{createHash,randomUUID}=require('node:crypto');
class PlatformClient{
 constructor({rpc,directory,clientId}){if(typeof rpc!=='function'||!path.isAbsolute(directory)||!/^[a-z0-9-]{3,60}$/.test(clientId))throw Error('CLIENT_CONFIG');this.rpc=rpc;this.file=path.join(directory,clientId+'.json');fs.mkdirSync(directory,{recursive:true});this.jobs=fs.existsSync(this.file)?JSON.parse(fs.readFileSync(this.file)):{};}
 save(){const tmp=this.file+'.'+randomUUID()+'.tmp';fs.writeFileSync(tmp,JSON.stringify(this.jobs),{flag:'wx'});fs.renameSync(tmp,this.file);}
 async readiness(){const s=await this.rpc('adapter_status',{});return{version:s.contract?.appVersion||null,protocolVersion:s.contract?.protocolVersion||null,ready:!s.paused&&!s.recoveryMode&&s.executorEnabled===true&&['adapter_request_submit','adapter_request_result'].every(m=>s.contract?.methods?.includes(m)),paused:!!s.paused};}
 async submit({requestId,text,parentRequestId=null}){if(!/^[a-f0-9-]{36}$/.test(requestId||'')||typeof text!=='string'||!text.trim()||text.length>8000)throw Error('REQUEST_INVALID');const digest=createHash('sha256').update(JSON.stringify({text,parentRequestId})).digest('hex'),old=this.jobs[requestId];if(old){if(old.digest!==digest)throw Error('REQUEST_CONFLICT');return{...old,duplicate:true};}const parent=parentRequestId?this.jobs[parentRequestId]:null;if(parentRequestId&&(!parent?.adapterId||parent.state!=='answered'))throw Error('PARENT_NOT_ANSWERED');if(!(await this.readiness()).ready)throw Error('ADAPTER_NOT_READY');const row={requestId,digest,state:'submitting',adapterId:null};this.jobs[requestId]=row;this.save();try{const r=await this.rpc('adapter_request_submit',{clientRequestId:requestId,text,...parent?{parentId:parent.adapterId}:{}});if(!/^[a-f0-9-]{36}$/.test(r.id||''))throw Error('RESPONSE_INVALID');row.adapterId=r.id;row.state='accepted';this.save();return{...row};}catch(e){row.state='unknown';this.save();throw Error('SUBMISSION_UNKNOWN_NO_RETRY');}}
 async result(requestId){const row=this.jobs[requestId];if(!row?.adapterId)throw Error('REQUEST_NOT_OWNED_OR_UNKNOWN');const r=await this.rpc('adapter_request_result',{id:row.adapterId});if(r.id!==row.adapterId)throw Error('RESULT_MISMATCH');row.state=r.status;this.save();return{requestId,adapterId:r.id,state:r.status,reply:r.reply||null};}
}
module.exports={PlatformClient};
